// Ambil output AI
let rawOutput = $input.item.json.output || "";

// Hapus tag think & code fences
let cleanText = rawOutput
  .replace(/<think>[\s\S]*?<\/think>/gi, '')
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

function extractJson(s) {
  const start = s.indexOf('{');
  const end = s.lastIndexOf('}');
  if (start === -1 || end === -1 || end <= start) return null;
  try { return JSON.parse(s.slice(start, end + 1)); } catch (e) { return null; }
}

const aiData = extractJson(cleanText) || {};

// Ambil result_id dari webhook
let resultId = null;
try {
  resultId = $('Webhook1').first().json.body.result_id;
} catch (e) {
  resultId = null;
}

// Setiap field diminta bilingual: { en: "...", id: "..." }.
// Fallback ke string polos kalau model mengabaikan skema bilingual.
function pick(field, lang) {
  if (!field) return '';
  if (typeof field === 'string') return field;
  return field[lang] || field.en || field.id || '';
}

const priorityLevel = (aiData.prioritization_level && aiData.prioritization_level.level) || '';

return {
  result_id: resultId,
  prioritization_level: priorityLevel,
  ai_recommendation_en: pick(aiData.strategic_recommendation, 'en'),
  ai_recommendation_id: pick(aiData.strategic_recommendation, 'id'),
  action_plan_en: pick(aiData.action_plan, 'en'),
  action_plan_id: pick(aiData.action_plan, 'id'),
  control_insight_en: pick(aiData.control_insight, 'en'),
  control_insight_id: pick(aiData.control_insight, 'id'),
  impact_interpretation_en: pick(aiData.impact_interpretation, 'en'),
  impact_interpretation_id: pick(aiData.impact_interpretation, 'id')
};
